4.주제 만들기: 하나님의 지혜와 전도

5.하나님 찾기(관찰)

- 이 세상이 자기 지혜로 하나님을 알지 못하므로 하나님께서는 전도의 미련한 것으로 믿는 자들을 구원하시기를 기뻐하셨다.

- 그리스도는 하나님의 능력이요 하나님의 지혜이다.

- 하나님의 어리석음이 사람보다 지혜롭고 하나님의 약하심이 사람보다 강하다.

- 아무 육체도 하나님 앞에서 자랑하지 못하게 하려 하심

- 자랑하는 자는 주 안에서 자랑하라 함과 같게 하려 하심

6.인간 찾기(관찰)

- 세상의 지혜로는 하나님을 알지 못한다

- 유대인은 표적을 구하고 헬라인은 지혜를 찾는다

- 바울 일행은 십자가에 못 박힌 그리스도를 전하지만,

- 이것은 유대인에게는 거리끼는 것이요 이방인에게는 미련한 것이다.

7.하나님 찾기(해석)

- 하나님을 알지 못하고 구원받는 방법을 모르는 사람들을 위해 하나님께서 십자가 복음을 계획하시고 실천하셨다

- 그리스도는 사람의 능력과 지혜로는 도저히 할 수도 없고 생각해낼 수도 없는 놀라운 놀라운 능력이요 지혜이다. 

- 하나님의 지혜와 강함은 사람과 비교할 수 없이 크다. 인류의 모든 지성과 과학의 힘을 합친다고 할지라도 하나님과 비교할 수는 없다.

- 십자가 복음을 믿는 자들이 믿지 않는 자들을 전도함으로 복음이 전해지는 것은 구원이 사람의 지혜와 능력으로 이루어지는 것이 아니라, 오직 예수 그리스도를 믿음으로 이루어지는 것을 사람이 깨닫게 하기 위함이다.

- 구원은 하나님의 선물이기 때문에 사람은 자신의 믿음과 크고 작음으로 자랑할 수가 없는 것이다.

- 자랑할 자는 모든 것을 이루시는 주 안에서 자랑해야 한다. 

8.인간 찾기(해석)

- 유대인은 예수님께 표적을 구했고, 예수님은 요나의 표적을 말씀하시며 인류를 구원할 십자가를 담당하시고 사흘 만에 부활, 승천하셨다.

- 헬라철학이 발달한 헬라인들에게는 철학이 중요했기에 십자가 복음은 미련해 보였다.

- 바울 일행이 십자가 복음을 전하지만, 그들에게 이것은 거리끼고 미련한 것일 뿐이다.

- 유대인은 율법과 자신들의 노력이 중요했고, 헬라인에게는 대단해 보일 수 있는 지성과 자신들이 쌓아온 지식이 중요했다.

9.적용(나) 

- 나를 구원하신 하나님께 감사하는 삶을 살고,

- 지인들에게 하나님을 자랑하고,

- 과학과 지성을 중요시하는 현대인들에게 십자가 복음을 전해야겠다.

