7. 하나님 찾기 (해석) 

- 믿어지면 하나님의 계획이 얼마나 놀라운지 깨달을 수 있다.

- 믿어지는 것은 하나님의 은혜이고, 믿음이 내게 주어진 것은 참으로 감사한 일이다.

- 하나님께서는 만세전부터 모든 것을 계획하셨다. 지금도 그 계획 가운데 있다.

- 하나님은 우리를 너무 사랑하셔서, 그의 아들과 성령까지 보내주셨다.

- 이 사랑이 너무 놀랍다.

- 치밀하시고 실수가 없으신 하나님의 계획에 감사드린다.

8. 인간(해석):

- 바울은 고린도 성도들에게 복음을 전할 때 자신은 약하고 두려워 심히 떨었지만 자신의 지혜가 아닌 성령의 나타내심과 능력으로 전했음을 고백했다.

- 그리고 이 지혜가 고린도 성도들의 믿음이 되길 소망했다.

- 바울과 같이 굳건한 사도도 두려웠고, 떨었다. 복음을 전하는 것은 그런 것이다.

- 그러나 인간의 연약함을 덮으시는 하나님의 능력은 바울이 담대하게 복음을 선포할 수 있게 만들었다.

- 우리의 삶도 같을 것이다. 

- 이 시대에 복음을 전하는 것은 두려운 일이 되었다.

- 사람들은 복음을 미신적인 것으로 여기고, 비과학적인 것으로 바라본다. 

- 눈으로 보지 못하고 귀로 듣지 못하고 마음으로 생각하지 못하는 상태에 놓여있다.

- 그들을 위해 간절한 마음과 하나님의 능력을 의지함으로 복음을 전해야겠다.

- 나는 할 수 없지만 하나님은 일하신다. 그분의 능력을 의지하며 복음을 전해야한다.

9. 적용(나):

- 두렵고 떨리는 마음이 아직 남아있지만 하나님의 능력으로 복음이 선포될 것을 의지하며 담대하게 복음을 전해야겠다. 

