4. 주제 만들기

결혼의 이유와 절제

  

5. 하나님 찾기(관찰)

은사를 주신 하나님 

6.인간 찾기(관찰)

음행의 마음과 절제할 수 없으면 결혼할 것을 권면하는 바울

자신처럼 그러한 은사가 있다면 독신이 좋다고 말하는 바울.

