복음으로 말미암아 살리시는 주님 

6.인간 찾기(관찰)

복음을 위하여 지신의 권리를 절제하는 바울

많은 영혼을 위하여 맞춤형 전도하는 바울

  

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

바울은 복음의 참된 일꾼이다. 당시 바울의 위치는 사도로서 충분히 자신의 권리를 주장하며 사역할 수 있는 상황이었다. 

그 권리 중 하나는 사역비를 사용할 수 있는 정당한 권리였을 것이다. 충분한 사역비를 받아 사용하는 것도 합당한 일이었음에도, 바울은 교회에 부담을 주지 않기 위해, 그리고 자신의 믿음을 지키기 위해 가난을 선택한 것처럼 보인다.

이는 바울이 물질의 유혹으로부터 완전히 자유로운 영혼이었음을 보여준다. 

그는 사명자는 복음을 전하는 일로 결코 망하지 않을 것임을 분명히 확신하고 있었다. 

이러한 바울의 태도는 오늘날 우리에게 큰 도전이 된다.

사역에 사용되는 물질로부터 자유로웠던 바울의 모습을 생각해 볼 때, 그 원동력은 철저히 자신을 ‘주의 종’으로 여기는 충성심에서 출발했다고 보인다. 

사역과 복음 전파의 주체, 즉 주인은 사역을 수행하는 종이 아니라 하나님이시라는 사실을 그는 분명히 알고 있었다.

바울은 단 한 영혼에게라도 복음이 전파될 수 있다면, 지혜를 발휘하여 상대에 맞는 맞춤형 전도 전략을 사용했다. 

자신을 갑옷처럼 둘러싸고 있던 무거운 율법 의식이 때로는 순수한 복음 전파에 장애물이 된다고 판단할 때, 그는 그것을 과감히 내려놓았다. 

바울은 자신의 체면보다 영혼을 진정으로 사랑하는 사람이었음을 발견하게 된다.

주님의 사랑이 특별히 필요한 이 시대에, 바울과 같은 지혜롭고 순수한 전도 방식이 더욱 절실히 요구되는 때임이 분명하다.

9. 삶의 적용(구체적으로)

나의 권리를 주장하지 말고 오직 주님의 사랑으로 사역을 감당하여야겠다. 오늘도 목마른 영혼들을 위하여 중보기도 해야겠다.

