4. 주제만들기: 내 몸은 거룩한 주님의 성전

5. 하나님 찾기 (관찰)

- 잡히시던 밤에 축하하신 후 떡을 먹게하시고, 잔을 마시게한 예수님 

6. 인간 찾기 (관찰)

- 먹을 때에 먼저 먹고 취한자가 있으며 교회를 업신여기고, 빈궁한 자를 부끄럽게 여기고 있다고 말하는 바울

- 성찬식은 주님이 오실 때까지 전하는 일에 힘써야 됨을 알려주는 바울

- 떡과 잔을 합당하시 않게 마시는 자는 죄를 짓는 것이라 말하는 바울

7. 하나님 찾기 (해석) 

- 예수님은 잡혀가실 그날 밤에도 우리를 위하여 떡을 떼어주시고, 잔을 마시게 하셨다.

- 하나님의 사랑은 그 크기를 도저히 알 수 없다.

8. 인간(해석):

- 바울은 믿음을 선택한 자들이 형식적인 신앙에 빠지는 것을 질책했다.

- 공동체를 배려하지 않고 먼저 먹고 취하는 성도들, 교회를 업신여긴 성도들, 빈궁한 자를 챙기지 않는 성도들의 모습은, 오늘날 우리의 교회와 비슷한 모습이다.

- 개인의 신앙생활은 있지만 공동체를 위한 신앙생활은 없는 나의 신앙생활도 반성하고 점검해보아야 한다.

- 자기중심적인 신앙생활에 빠지게하는 사탄의 전략에 속아서는 안되겠다.   

9. 적용(나): 

- 개인의 신앙생활도 중요하지만, 공동체를 사랑으로 섬길 수 있는 마음이 내 안에 가득하길 소망한다.

10. 영적터치(단어/구절)

- 교회를 업신여기고 빈궁한 자들을 부끄럽게 하느냐

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-01-26', '고린도전서', '11장 11~20절', '모든 것을 창조하신 하나님', '(고린도전서 11장)

11. 그러나 주 안에는 남자 없이 여자만 있지 않고 여자 없이 남자만 있지 아니하니라

12. 이는 여자가 남자에게서 난 것 같이 남자도 여자로 말미암아 났음이라 그리고 모든 것은 하나님에게서 났느니라

13. 너희는 스스로 판단하라 여자가 머리를 가리지 않고 하나님께 기도하는 것이 마땅하냐

14. 만일 남자에게 긴 머리가 있으면 자기에게 부끄러움이 되는 것을 본성이 너희에게 가르치지 아니하느냐

15. 만일 여자가 긴 머리가 있으면 자기에게 영광이 되나니 긴 머리는 가리는 것을 대신하여 주셨기 때문이니라

16. 논쟁하려는 생각을 가진 자가 있을지라도 우리에게나 하나님의 모든 교회에는 이런 관례가 없느니라

17.  내가 명하는 이 일에 너희를 칭찬하지 아니하나니 이는 너희의 모임이 유익이 못되고 도리어 해로움이라

18. 먼저 너희가 교회에 모일 때에 너희 중에 분쟁이 있다 함을 듣고 어느 정도 믿거니와

19. 너희 중에 파당이 있어야 너희 중에 옳다 인정함을 받은 자들이 나타나게 되리라

20. 그런즉 너희가 함께 모여서 주의 만찬을 먹을 수 없으니

