6. 인간 찾기 (관찰)

- 모든 은사는 한 성령이 행하며, 우리의 몸은 여러 지체가 연합되어 있고, 이는 한 몸이고, 떨어질 수 없음을 말하는 바울

7. 하나님 찾기 (해석) 

- 하나님께서 원하시는대로 우리의 몸을 지으셨다.

- 놀랍게도 우리의 몸은 각 지체마다 맡은 기능이 있다. 그 역할이 각각 다르고, 어느 것이 어느 것을 대체할 수 없다. 

- 하나님은 위대하시고, 놀라운 분이시다.

8. 인간(해석):

- 하나님은 우리를 각자 다른 존재로 만드셨다.

- 그 분의 입장에선 아주 완벽한 인간 한 형태를 만들어 동일하게 찍어내면 하나님을 경외하는 것과 죄에 대한 리스크를 줄일 수 있었을텐데 그렇게 하지 않으셨다.

- 한 사람의 존재를 더욱 소중히 생각하고, 모든 사람을 동일하게 사랑하는 하나님의 존재를 더욱 깊이 깨닫게하기 위함이 있을 수도 있다.

- 우리는 각자 다르지만 신앙 안에서는 하나의 지체이다. 서로 다르게 주어진 은사를 바탕으로 각자의 역할을 잘 감당하여야 한다.

- 한 지체가 빠지면 다른 지체로 대체할 수 없기 때문에 각 지체는 서로 높고 낮음이 있을 수 없다.

- 그러므로 공동체 안에서 내가 어떠한 모습으로 공동체를 섬겨야하는지 분명하다. 

- 겸손과 사랑. 나는 남보다 뛰어나지 않으며, 공동체 구성원을 진심으로 사랑할 수 있어야 한다.

- 남북청년연합 선교회도 각기 다른 지체가 연합되어 있다. 서로의 역할을 잘 감당하는 공동체가 되길 소망한다.

9. 적용(나): 

- 겸손한 마음으로 공동체를 섬기고, 한 몸, 한 성령임을 잊지 않도록 노력해야겠다.

