8. 인간(해석):

- 현대와 같이 정보가 넘치고, 어느 곳에서든 성경과 말씀을 들을 수 있는 것과는 다르게, 성경과 말씀을 자유롭게 보지 못했던 당시 상황에서의 바울의 심정이 느껴진다.

- 바울은 소중히 전해진 복음이 잘 유지되고, 성도가 교회에서 연합하여, 복음이 변질되지 않길 소망했을 것이다.

- 이미 수많은 시행착오를 눈과 귀로 보았기에 그의 간절함이 얼마나 컸을까? 

- 이 시대를 살아가는 우리가 바울과 같은 간절함으로 복음을 전할 수 있기를 소망해 본다.

- 바울은 은혜받은 자임을 깨닫고 고백한다.

- 만삭되지 못하여 난 자 같다는 표현은 미숙아를 뜻할 것이다. 

- 당시 미숙아가 살 수 있는 확률은 몇 %였을까? 1%가 안 되었을 것이다. 

