8. 인간 찾기(해석)

바울은 육체의 지혜가 아니라 주님의 은혜와 거룩함, 그리고 진실하므로 행동해야 함을 말하고 있다. 참다운 그리스도인은 모든 것이 하나님의 은혜로부터 시작되고, 또한 은혜로 마무리된다는 자세가 필요하다.

당시 바울은 매우 똑똑하고 지식이 많은 사람이었지만, 주님을 만난 이후에는 모든 것이 자신의 의가 아니라 오직 하나님의 은혜임을 강조하였다. 그는 자신을 자랑하던 삶에서 벗어나 오직 주님 안에서만 자랑하는 사람이 되었음을 말한다.

14절에 보면 “너희가 우리를 부분적으로 알았으나 우리 주 예수의 날에는 너희가 우리의 자랑이 되고 우리가 너희의 자랑이 되리라”라고 기록되어 있다. 이 말씀을 통해 마지막 날에는 모든 것이 분명히 드러나고 온전히 알게 된다는 사실을 깨닫게 된다.

결국 신자가 자랑할 것은 우리가 어떤 일을 했느냐가 아니라, 죄인이었던 우리를 하나님께서 용서하시고 은혜 가운데 어떻게 사용 받았는가 하는 것이다.

나를 포함하여 우리 남청연 모두가 주님의 날에 주님 앞에서 서로 자랑할 이야기가 많이 있기를 소망한다.

