- 교회 내에 바울을 근심하게 한 자가 있었고, 그로 인해 갈등이 심했던 것으로 보인다

- 바울이 편지를 쓴 이유는 근심하게 함이 아니라 넘치는 사랑을 전하기 위함이었다

- 교회에서는 근심하게 한 자로 인해 많은 근심 또는 분열이 일어난 것으로 보인다

- 이 일로 교회에서는 그에게 징계를 주었고 그는 슬픔을 느끼며 회개한 것으로 보인다

- 바울은 이제 교회에서 그를 용서하고 위로하기를 권면한다

- 회개한 자를 슬픔에서 건져내어 사랑을 나타내라고 한다

- 그리고 순종하는지 보려고 이 편지를 썼다고 말함으로써 그 사람을 용서하고 사랑으로 감싸주라는 것을 강조한다

- 내용을 보면 그 사람은 매우 큰 잘못을 저질렀고, 이 것이 교회에 중대한 사안이었음을 알 수 있다.   

9.적용(나) 

