7. 하나님 찾기(해석)

8. 인간 찾기(해석)

모세가 율법이 새겨진 돌판을 들고 산에서 내려올 때, 그의 얼굴에 비친 하나님의 영광 때문에 사람들이 그를 바라볼 수 없을 정도였다고 바울은 성경을 인용하여 말하고 있다. 

바울은 이러한 사실을 통해 돌판에 새겨진 율법보다 더 위대한 예수 그리스도의 영광에 관해 설명한다.

즉, 예수 그리스도께서 죄인을 위하여 죽으시고 부활하심으로 세워진 새로운 성령의 법이 구약의 율법보다 얼마나 더 큰 하나님의 영광을 드러내는지를 강조하고 있다. 그는 심지어 성도들을 향하여 “너희는 그리스도의 편지”라고 표현하기도 한다.

돌판에 새겨진 글자가 아니라 사람의 마음에 새겨진 말씀이라는 사실은 하나님과 인간 사이의 더욱 깊고 친밀한 관계를 떠올리게 한다. 

이러한 사실을 생각할 때, 하나님께서 인간의 마음에 복음의 정신을 새기실 만큼 우리를 얼마나 깊이 사랑하시는지를 가늠할 수 있다.

그러므로 세상의 어떤 부귀영화도 한 영혼에 허락하신 하나님의 편지와 같은 가치를 결코 대신할 수 없다. 바울은 오직 예수 그리스도 안에서만 참된 기쁨과 만족이 있음을 분명하게 밝히고 있다.

9. 적용 (구체적으로)

내가 그리스도의 편지임을 생각할 때 얼마나 소중한 존재로 여김을 받는지 느끼게 된다. 나 같은 죄인을 아들로 삼아주시고 품어주시는 하나님 아버지께 감사를 올리는 시간을 보내야겠다. 

 

