- 언어와 행동이 믿지 않는 자들에게 많은 영향을 미침을 알 수 있다.

- 우리의 언어와 행동은 성령 안에서 이루어짐을 인식하고, 믿지 않는 자들이 시험 들지 않도록 하여야 한다.

