6. 인간 찾기 (관찰)

- 너그럽게 한 연보로 그들이 하나님께 감사드리게 될 것이라 말하는 바울

- 봉사의 직무는 성도들의 부족한 것을 보충하고 하나님께 드리는 감사로 풍성해질 것이라 말하는 바울

- 이러한 증거는 그리스도의 복음을 진실히 믿고 순종하는 것으로 그들은 하나님께 영광 돌릴 것이라 말하는 바울

- 그들은 너희를 위해 간구하고 받은 은혜로 사모할 것이라 말하는 바울

- 말로 다할 수 없는 은사를 주신 하나님께 감사드리는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):

- 오늘 말씀을 통해 깨닫게 된 것은, 물질적인 섬김과 후원이 단순한 도움의 차원을 넘어 하나님께 영광이 되는 영적인 통로라는 사실이다.

- 우리는 종종 후원을 누군가의 부족을 채워주는 행위로만 생각하기 쉽다. 후원은 단순히 필요를 채우는 데서 끝나지 않고, 도움을 받는 사람들로 하여금 하나님께 감사하게 하고, 하나님께 영광을 돌리게 하는 통로가 된다.

- 또한 그들은 도움을 준 사람들을 위해 기도하며, 그 안에서 하나님의 은혜를 더욱 깊이 경험하게 된다. 즉, 후원은 사람과 사람 사이의 거래가 아니라, 하나님의 은혜가 흐르는 영적 순환이 되는 것이다.

- 후원을 하는 사람 역시 단순히 주는 역할에서 끝나지 않는다. 보냄을 통해 기쁨과 감사가 넘치게 되고, 하나님께서 자신의 삶을 사용하신다는 사실 속에서 더 큰 은혜를 경험하게 된다.

- 우리는 누구나 후원하는 사람이 될 수 있고, 도움을 받는 사람이 될 수 있다. 어느 순간에든 하나님께서 주신 감사의 은혜를 잊지 말아야 한다. 

9. 적용(나): 

- 후원을 하는 순간에는 교만함이 없도록, 도움을 받는 순간에는 하나님께 감사가 넘치기를 기도한다.

- 주변에 도움이 필요한 이웃을 살펴보아야겠다. 

