8. 인간 찾기(해석)

진정한 인정은 사람에게서 오는 것이 아니라 하나님으로부터 받는 것이다. 

사도 바울은 자신을 높이며 자화자찬하는 태도를 결코 참된 인정으로 보지 말라고 분명히 경계한다. 

설령 교회의 확장을 위해 열심히 일하는 사람이라 할지라도, 그 마음의 중심을 늘 돌아보며 조심해야 한다는 것이다.

특히 바울은 다른 사람이 오랜 시간 수고하여 세워 온 교회를 마치 자신이 처음부터 개척한 것처럼 여기거나 행동하는 태도를 경계한다. 이는 단순한 실수가 아니라, 하나님 앞에서 겸손을 잃어버리는 위험한 모습이기 때문이다.

오히려 신자는 하나님께서 각자에게 맡기신 비전과 영역을 분별하고, 다른 사람의 터가 아닌 자신의 자리에서 충성되게 개척하며 나아가야 한다. 그것이 하나님 앞에서 바른 자세이다.

또한 바울은 믿음이 자라갈수록 규범을 지키며, 영적으로 더욱 풍성해지는 삶을 살아가야 함을 강조한다. 

이러한 삶 속에서 우리는 점점 더 하나님을 의지하게 되고, 사람의 인정이 아닌 하나님의 시선을 바라보게 된다.

결국 우리가 수고한 모든 일에 대한 참된 칭찬과 자랑은 사람에게서가 아니라, 오직 주께서 인정하실 때 비로소 온전하고 풍성해진다는 진리를 깨닫게 된다.

