8. 인간(해석):

오늘 말씀을 묵상하며 마음에 깊이 다가온 것은, 인간의 욕심은 시대를 초월하여 동일하게 존재한다는 사실이다. 과거 고린도교회 안에서도 거짓 사도들이 성도들을 미혹하여 자신의 유익을 위해 복음을 왜곡하고 재물을 취했던 것처럼, 오늘날에도 여전히 비슷한 일들이 반복되고 있다. 성도들은 하나님을 사랑하는 마음으로 가장 좋은 것을 드리고 싶어 한다. 그러나 그 순수한 마음이 때로는 미혹의 통로가 되기도 한다. 

그래서 반드시 필요한 것은 영적으로 깨어 있음과 분별력이다.

우리는 감정이나 분위기가 아니라 하나님 말씀 위에서 판단할 수 있어야 한다. 결국 미혹하는 자뿐만 아니라 분별하지 못하고 따르는 자에게도 책임이 있다.

바울은 고린도 성도들에게 조금의 부담도 주지 않기 위해 스스로를 철저히 절제하며 사역했다. 그는 자신의 권리를 주장하기보다 복음이 오해받지 않도록 자신을 낮추는 길을 선택했다.

오늘날에도 이와 같이 살아가는 수많은 목회자, 선교사, 사역자들이 있다.

보이지 않는 곳에서 묵묵히 헌신하고, 아무 대가 없이 섬기며, 복음을 위해 자신의 삶을 드리는 사람들이다. 그러나 안타깝게도 거짓된 사역자들과 사기꾼들로 인해 이들의 헌신마저 왜곡되어 보일 때가 많다.

하나님은 모든 것을 보고 계신다. 사람의 눈에는 드러나지 않는 헌신과 눈물, 아무도 알아주지 않는 수고와 충성은 결코 사라지지 않는다. 이 땅에서는 오해받을 수 있지만, 하늘 나라에서는 반드시 큰 상급과 열매로 드러날 것이다.

